      "description": "Evaluatiedekking naast de kwaliteitsscore (DEF-624). Een lagere dekking mag nooit als hogere kwaliteit verschijnen; daarom staan score en dekking hier los van elkaar.",
      "required": [
        "evaluated",
        "passed",
        "failed",
        "review_required",
        "not_evaluated",
        "error",
        "total",
        "coverage_ratio"
      ],
      "properties": {
        "evaluated": {
          "type": "integer",
          "minimum": 0,
          "description": "Aantal regels met status pass of fail"
        },
        "passed": {
          "type": "integer",
          "minimum": 0
        },
        "failed": {
          "type": "integer",
          "minimum": 0
        },
        "review_required": {
          "type": "integer",
          "minimum": 0,
          "description": "Regels die menselijk oordeel vragen"
        },
        "not_evaluated": {
          "type": "integer",
          "minimum": 0,
          "description": "Regels waarvoor vereiste invoer ontbrak"
        },
        "error": {
          "type": "integer",
          "minimum": 0,
          "description": "Regels waarvan de evaluator faalde"
        },
        "not_applicable": {
          "type": "integer",
          "minimum": 0,
          "description": "DEF-766 (2.1.0, optioneel voor oudere resultaten): regels met een afgeronde, gemotiveerde niet-toepasselijkheid; telt niet als geëvalueerd (pass/fail), niet als open en niet als niet-uitgevoerd"
        },
        "total": {
          "type": "integer",
          "minimum": 0,
          "description": "Totaal beoordeelde rule-IDs"
        },
        "coverage_ratio": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "evaluated gedeeld door total"
        }
      },
      "additionalProperties": false
    },
    "review_required": {
      "type": "array",
      "description": "Regels die een inhoudelijk oordeel vragen (DEF-624). Geen violations: zij tellen niet als kwaliteitsprobleem en niet als pass.",
      "items": {
        "type": "object",
        "required": ["rule_id", "category", "reason", "signals"],
        "properties": {
          "rule_id": {
            "type": "string",
            "minLength": 1
          },
          "category": {
            "type": "string",
            "enum": ["taal", "juridisch", "structuur", "samenhang", "system"]
          },
          "reason": {
            "type": "string",
            "description": "Waarom de regel menselijk oordeel vraagt"
          },
          "signals": {
            "type": "array",
            "description": "Patroontreffers die de reviewer wijzen waar te kijken; aanwijzing, geen bewijs",
            "items": {
              "type": "string"
            }
          }
        },
        "additionalProperties": false
      }
    },
    "validation_status": {
      "type": "string",
      "enum": ["validated", "validation_unknown"],
      "description": "Uitkomst van de validatie als geheel (DEF-621/DEF-624). Verplicht en zonder default: validated betekent uitsluitend dat een producent werkelijk een run uitvoerde (een fail, open review of technische regelfout blijft validated — runstatus is niet de kwaliteitsuitkomst). Bij validation_unknown is er geen betrouwbaar uitgevoerde run: de regelset dekt het contract niet, de status ontbrak of was ongeldig, of de service faalde; dat is technisch niet te bepalen, niet inhoudelijk invalid."
    },
    "unknown_reason": {
      "type": "string",
      "enum": [
        "ruleset_incomplete",
        "contract_status_missing",
        "contract_status_invalid",
        "validation_error"
      ],
      "description": "Machineleesbare reden bij validation_unknown; een consumer matcht erop, de onderliggende oorzaak hoort in het log. ruleset_incomplete: de geladen regelset dekt het contract niet (DEF-621, met validation_readiness). contract_status_missing: het bronresultaat droeg geen (of null) validation_status — er is geen run vastgelegd (DEF-624). contract_status_invalid: het bronresultaat droeg een waarde buiten het contract (DEF-624). validation_error: de validatieservice faalde (degraded result)."
    },
    "validation_readiness": {
      "type": "object",
      "description": "Waarom de regelset het contract wel of niet dekt (DEF-621). expected_total telt de contractuele rule-ID-set, niet de bestanden op schijf.",
      "required": [
        "ready",
        "expected_total",
        "loaded_total",
        "missing_rule_ids",
        "unexpected_rule_ids"
      ],
      "properties": {
        "ready": { "type": "boolean" },
        "expected_total": { "type": "integer", "minimum": 0 },
        "loaded_total": { "type": "integer", "minimum": 0 },
        "missing_rule_ids": { "type": "array", "items": { "type": "string" } },
        "unexpected_rule_ids": { "type": "array", "items": { "type": "string" } }
      },
      "additionalProperties": false
    }
  },
  "allOf": [
    {
      "if": {
        "properties": { "validation_status": { "const": "validation_unknown" } },
        "required": ["validation_status"]
      },
      "then": {
        "properties": {
          "overall_score": {
            "enum": [0, null],
            "description": "Fail-closed placeholder (DEF-621) of null (niet beschikbaar, DEF-622); nooit een oordeel."
          },
          "is_acceptable": { "const": false }
        },
        "required": ["unknown_reason"]
      }
    },
    {
      "if": {
        "properties": { "validation_status": { "const": "validated" } },
        "required": ["validation_status"]
      },
      "then": {
        "not": { "required": ["unknown_reason"] }
      }
    },
    {
      "if": {
        "properties": { "unknown_reason": { "const": "ruleset_incomplete" } },
        "required": ["unknown_reason"]
      },
      "then": {
        "required": ["validation_readiness"]
      }
    }
  ],
  "additionalProperties": false
}

